from __future__ import annotations

import argparse
import importlib
from pathlib import Path
from typing import Iterable, List, Optional, Sequence, Tuple

from DataRepresentation import BDB, DTPR, MTPR, PTPR, TPQN


DEFAULT_COMMENTS = [
    "Generated by dtpr_to_qpr.py",
    "Assumption: each BDB beat corresponds to a quarter note.",
]


def midi_pitch_to_sitch(pitch: int) -> str:
    if pitch < 0:
        return "R"

    names = ["C", "C#", "D", "Eb", "E", "F", "F#", "G", "G#", "A", "Bb", "B"]
    octave = pitch // 12 - 1
    return f"{names[pitch % 12]}{octave}"


def sorted_beats(bdb: BDB):
    return sorted(bdb.beats.values(), key=lambda beat: (beat.beat_time, beat.id))


def sorted_mtpr_notes(mtpr: MTPR):
    return sorted(
        mtpr.notes.values(),
        key=lambda note: (note.abs_ontick, note.abs_offtick, note.id),
    )


def infer_last_stime(beats, notes) -> int:
    last_note_tick = max((note.abs_offtick for note in notes), default=0)
    last_beat_tick = max(0, (len(beats) - 1) * TPQN)
    return max(last_note_tick, last_beat_tick)


def align_last_stime_to_barline(last_stime: int, meter_start: int, barlen: int) -> int:
    if barlen <= 0:
        return last_stime

    relative = last_stime - meter_start
    if relative <= 0:
        return meter_start

    remainder = relative % barlen
    if remainder == 0:
        return last_stime
    return last_stime + (barlen - remainder)


def infer_meter_events(
    beats,
    last_stime: int,
    *,
    align_end_to_barline: bool = True,
) -> List[Tuple[int, int, int, int]]:
    if not beats:
        aligned_last_stime = (
            align_last_stime_to_barline(last_stime, 0, 4 * TPQN)
            if align_end_to_barline
            else last_stime
        )
        return [(0, 4, 4, 4 * TPQN), (aligned_last_stime, 0, 0, 0)]

    downbeat_indices = [idx for idx, beat in enumerate(beats) if beat.is_downbeat]
    if not downbeat_indices:
        downbeat_indices = [0]

    full_bar_spans = [
        right - left
        for left, right in zip(downbeat_indices, downbeat_indices[1:])
        if right > left
    ]
    default_numer = full_bar_spans[0] if full_bar_spans else 4
    current_numer = max(1, default_numer)
    meter_events: List[Tuple[int, int, int, int]] = []

    first_downbeat = downbeat_indices[0]
    if first_downbeat > 0:
        pickup_barlen = first_downbeat * TPQN
        meter_events.append((0, current_numer, 4, pickup_barlen))
        meter_events.append((first_downbeat * TPQN, current_numer, 4, current_numer * TPQN))
    else:
        meter_events.append((0, current_numer, 4, current_numer * TPQN))

    for idx in range(1, len(downbeat_indices)):
        bar_start = downbeat_indices[idx]
        if idx < len(downbeat_indices) - 1:
            numer = downbeat_indices[idx + 1] - downbeat_indices[idx]
        else:
            numer = current_numer

        numer = max(1, numer)
        if numer != current_numer:
            meter_events.append((bar_start * TPQN, numer, 4, numer * TPQN))
            current_numer = numer

    last_meter_start, _, _, last_barlen = meter_events[-1]
    aligned_last_stime = (
        align_last_stime_to_barline(last_stime, last_meter_start, last_barlen)
        if align_end_to_barline
        else last_stime
    )
    meter_events.append((aligned_last_stime, 0, 0, 0))
    return meter_events


def infer_spqn_events(beats) -> List[Tuple[int, float, float]]:
    if len(beats) < 2:
        return [(0, 0.5, 120.0)]

    events: List[Tuple[int, float, float]] = []
    prev_spqn: Optional[float] = None

    for beat_idx, (left, right) in enumerate(zip(beats, beats[1:])):
        spqn = right.beat_time - left.beat_time
        if spqn <= 0:
            continue

        if prev_spqn is None or abs(prev_spqn - spqn) > 1e-6:
            bpm = 60.0 / spqn
            events.append((beat_idx * TPQN, spqn, bpm))
            prev_spqn = spqn

    if not events:
        return [(0, 0.5, 120.0)]
    return events


def format_note_line(
    note_idx: int,
    note,
    ptpr_note=None,
    *,
    pitch_mode: str = "sitch",
    channel: int = 0,
    subvoice: int = 0,
    label: Optional[str] = None,
    include_performance: bool = False,
) -> str:
    if pitch_mode == "pitch":
        pitch_text = str(note.pitch)
    else:
        pitch_text = midi_pitch_to_sitch(note.pitch)

    label_text = str(note.id) if label is None else label

    fields = [
        str(note_idx),
        str(note.abs_ontick),
        str(note.abs_offtick),
        pitch_text,
        str(channel),
        str(subvoice),
        label_text,
    ]

    if (
        include_performance
        and ptpr_note is not None
        and ptpr_note.real_ontime is not None
        and ptpr_note.real_offtime is not None
    ):
        fields.append(f"{ptpr_note.real_ontime:.6f}")
        fields.append(f"{ptpr_note.real_offtime:.6f}")

    return "\t".join(fields)


def dtpr_to_qpr_text(
    dtpr: DTPR,
    *,
    name: Optional[str] = None,
    memo: Optional[str] = None,
    comments: Optional[Sequence[str]] = None,
    pitch_mode: str = "sitch",
    channel: int = 0,
    subvoice: int = 0,
    label: Optional[str] = None,
    include_performance: bool = False,
    program: int = 0,
    instrument_name: str = "Default",
) -> str:
    return structures_to_qpr_text(
        dtpr.BDB,
        dtpr.MTPR,
        dtpr.PTPR,
        name=name,
        memo=memo,
        comments=comments,
        pitch_mode=pitch_mode,
        channel=channel,
        subvoice=subvoice,
        label=label,
        include_performance=include_performance,
        program=program,
        instrument_name=instrument_name,
    )


def structures_to_qpr_text(
    bdb: BDB,
    mtpr: MTPR,
    ptpr: Optional[PTPR] = None,
    *,
    name: Optional[str] = None,
    memo: Optional[str] = None,
    comments: Optional[Sequence[str]] = None,
    pitch_mode: str = "sitch",
    channel: int = 0,
    subvoice: int = 0,
    label: Optional[str] = None,
    include_performance: bool = False,
    program: int = 0,
    instrument_name: str = "Default",
) -> str:
    if pitch_mode not in {"sitch", "pitch"}:
        raise ValueError("pitch_mode must be 'sitch' or 'pitch'")

    beats = sorted_beats(bdb)
    notes = sorted_mtpr_notes(mtpr)
    last_stime = infer_last_stime(beats, notes)

    comment_lines = list(DEFAULT_COMMENTS if comments is None else comments)
    meter_events = infer_meter_events(beats, last_stime)
    spqn_events = infer_spqn_events(beats)

    lines: List[str] = [f"// {comment}" for comment in comment_lines]

    if name:
        lines.append(f"# Name\t{name}")
    if memo:
        lines.append(f"# Memo\t{memo}")

    lines.append(f"# TPQN\t{TPQN}")
    lines.append(f"# Instr\t{channel}\t{program}\t{instrument_name}")
    lines.append("# Key\t0\tC\tmajor\t0")

    for stime, numer, denom, barlen in meter_events:
        lines.append(f"# Meter\t{stime}\t{numer}\t{denom}\t{barlen}")

    for stime, value, bpm in spqn_events:
        lines.append(f"# SPQN\t{stime}\t{value:.6f}\t{bpm:.6f}")

    for note_idx, note in enumerate(notes):
        ptpr_note = None if ptpr is None else ptpr.notes.get(note.id)
        lines.append(
            format_note_line(
                note_idx,
                note,
                ptpr_note,
                pitch_mode=pitch_mode,
                channel=channel,
                subvoice=subvoice,
                label=label,
                include_performance=include_performance,
            )
        )

    return "\n".join(lines) + "\n"


def write_dtpr_to_qpr(
    dtpr: DTPR,
    output_path: str | Path,
    **kwargs,
) -> Path:
    output = Path(output_path)
    output.write_text(dtpr_to_qpr_text(dtpr, **kwargs), encoding="utf-8")
    return output


def write_structures_to_qpr(
    bdb: BDB,
    mtpr: MTPR,
    output_path: str | Path,
    ptpr: Optional[PTPR] = None,
    **kwargs,
) -> Path:
    output = Path(output_path)
    output.write_text(
        structures_to_qpr_text(bdb, mtpr, ptpr, **kwargs),
        encoding="utf-8",
    )
    return output


def load_factory_target(factory: str):
    if ":" not in factory:
        raise ValueError("factory must be in the form 'module:attribute'")

    module_name, attr_name = factory.split(":", 1)
    module = importlib.import_module(module_name)
    target = getattr(module, attr_name)
    return target() if callable(target) else target


def build_arg_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        description="Export a DTPR object to a minimal qpr text file."
    )
    parser.add_argument("output", help="Output qpr file path.")
    parser.add_argument(
        "--factory",
        required=True,
        help="Python target that returns a DTPR object, e.g. seed:build_seed_dtpr",
    )
    parser.add_argument("--name", default=None, help="Optional # Name field.")
    parser.add_argument("--memo", default=None, help="Optional # Memo field.")
    parser.add_argument(
        "--pitch-mode",
        choices=["sitch", "pitch"],
        default="sitch",
        help="Write note pitches as note names or MIDI numbers.",
    )
    parser.add_argument(
        "--with-performance",
        action="store_true",
        help="Append real on/off seconds when PTPR data is available.",
    )
    parser.add_argument("--channel", type=int, default=0, help="QPR channel value.")
    parser.add_argument("--subvoice", type=int, default=0, help="QPR subvoice value.")
    parser.add_argument(
        "--label",
        default=None,
        help="QPR note label. If omitted, the MTPR note id is written.",
    )
    parser.add_argument("--program", type=int, default=0, help="GM program number.")
    parser.add_argument(
        "--instrument-name",
        default="Default",
        help="Instrument name written in the # Instr line.",
    )
    return parser


def main(argv: Optional[Sequence[str]] = None) -> int:
    parser = build_arg_parser()
    args = parser.parse_args(argv)

    dtpr = load_factory_target(args.factory)
    if not isinstance(dtpr, DTPR):
        raise TypeError(f"{args.factory} did not produce a DTPR instance")

    write_dtpr_to_qpr(
        dtpr,
        args.output,
        name=args.name,
        memo=args.memo,
        pitch_mode=args.pitch_mode,
        channel=args.channel,
        subvoice=args.subvoice,
        label=args.label,
        include_performance=args.with_performance,
        program=args.program,
        instrument_name=args.instrument_name,
    )
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
